<?php
declare(strict_types=1);require_once __DIR__.'/includes/layout.php';login_required();$pdo=db();$id=post_int('id')?:filter_var($_GET['id']??0,FILTER_VALIDATE_INT);$r=['department_name'=>'','department_budget'=>''];if($id){$s=$pdo->prepare('SELECT * FROM department WHERE department_id=?');$s->execute([$id]);$r=$s->fetch()?:$r;}if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$name=post('department_name');$budget=(float)($_POST['department_budget']??0);if($id)$pdo->prepare('UPDATE department SET department_name=?,department_budget=? WHERE department_id=?')->execute([$name,$budget,$id]);else$pdo->prepare('INSERT INTO department(department_name,department_budget) VALUES(?,?)')->execute([$name,$budget]);flash('success','Department saved.');redirect('departments.php');}page_header($id?'Edit Department':'Add Department','departments');?>
<div class="page-head"><h1><?=$id?'Edit':'Add'?> Department</h1><a class="btn" href="departments.php">Back</a></div><form class="card form-grid" method="post"><?=csrf_field()?><input type="hidden" name="id" value="<?=$id?>"><label>Name<input name="department_name" value="<?=e($r['department_name'])?>" required></label><label>Budget<input type="number" step="0.01" name="department_budget" value="<?=e($r['department_budget'])?>" required></label><div class="full"><button class="btn primary">Save Department</button></div></form><?php page_footer();?>
